class Command(BaseCommand):
    help = 'Seeds 210 curated quotes across typing, focus, discipline, patience, consistency, mastery, and flow.'

    def handle(self, *args, **options):
        created_count = 0
        existing_count = 0
        for text, author, category in QUOTES_DATA:
            quote, created = Quote.objects.get_or_create(
                text=text,
                defaults={
                    'author': author,
                    'category': category,
                    'language': 'en',
                    'is_active': True,
                }
            )
            if created:
                created_count += 1
            else:
                existing_count += 1

        total = Quote.objects.count()
        self.stdout.write(self.style.SUCCESS(
            f'Quotes seeded: {created_count} created, {existing_count} existing, {total} total in database.'
        ))
